#include <iostream>
#include <vector>
#include <cmath>
using namespace std;
// Function to calculate prime factors of a number
vector<int> primeFactors(int n) {
    vector<int> factors;
    while (n % 2 == 0) {
        factors.push_back(2);
        n /= 2;
    }
    for (int i = 3; i <= sqrt(n); i += 2) {
        while (n % i == 0) {
            factors.push_back(i);
            n /= i;
        }
    }
    if (n > 2) {
        factors.push_back(n);
    }
    return factors;
}
// Function to find two prime numbers closest in value to the sum of the factors of 142
void findClosestPrimes() {
    int n = 142;
    vector<int> factors = primeFactors(n);
    int sum = 1 + n;
    for (int i = 0; i < factors.size(); i++) {
        sum += factors[i] + n/factors[i];
    }
    int lower = sum - n;
    int upper = sum + n;
    int closestLower = lower;
    int closestUpper = upper;
    while (!isPrime(closestLower)) {
        closestLower--;
    }
    while (!isPrime(closestUpper)) {
        closestUpper++;
    }
    cout << "The two prime numbers closest in value to the sum of the factors of 142 are: " << closestLower << " and " << closestUpper << endl;
}
// Function to check if a number is prime
bool isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}
int main() {
    findClosestPrimes();
    return 0;
}
