Imagine you have a list of 10 words, and you want to shuffle them in a way that no two words have the same letters in the same positions as any other two words. Here's one possible implementation:
function shuffleWords(words) {
  const shuffledWords = words.map(word => shuffleArray(word.split('')));
  const uniqueWords = getUniqueWords(shuffledWords);
  return uniqueWords;
}
function shuffleArray(array) {
  const shuffled = array.slice();
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled.join('');
}
function getUniqueWords(words) {
  const uniqueWords = [];
  for (const word of words) {
    let isUnique = true;
    for (const uniqueWord of uniqueWords) {
      if (word === uniqueWord) {
        isUnique = false;
        break;
      }
      const letters = word.split('');
      for (let i = 0; i < letters.length; i++) {
        if (letters[i] === uniqueWord[i]) {
          isUnique = false;
          break;
        }
      }
      if (!isUnique) {
        break;
      }
    }
    if (isUnique) {
      uniqueWords.push(word);
    }
  }
  return uniqueWords;
}
To use this function, you can pass an array of words as an argument, like this:
