		<button type="button" onclick="findSpecialNumber()">Find</button>
	</form>
	<p id="result"></p>
	<script>
		function findSpecialNumber() {
			var start = parseInt(document.getElementById("start").value);
			var end = parseInt(document.getElementById("end").value);
			var result = "";
			for (var i = start; i <= end; i++) {
				if (i == 1 || isPrime(i) || isComposite(i) || isDivisibleBy3(i)) {
					continue;
				}
				if (isSemiprime(i) || isSquareFree(i)) {
					result += i + " ";
				}
			}
			if (result == "") {
				result = "No special number found.";
			}
			document.getElementById("result").innerHTML = result;
		}
		function isPrime(n) {
			if (n <= 1) {
				return false;
			}
			for (var i = 2; i <= Math.sqrt(n); i++) {
				if (n % i == 0) {
					return false;
				}
			}
			return true;
		}
		function isComposite(n) {
			if (n <= 1) {
				return false;
			}
			for (var i = 2; i <= Math.sqrt(n); i++) {
				if (n % i == 0) {
					return true;
				}
			}
			return false;
		}
		function isDivisibleBy3(n) {
			if (n % 3 == 0) {
				return true;
			}
			return false;
		}
		function isSemiprime(n) {
			for (var i = 2; i <= Math.sqrt(n); i++) {
				if (n % i == 0 && isPrime(i) && isPrime(n/i)) {
					return true;
				}
			}
			return false;
		}
		function isSquareFree(n) {
			for (var i = 2; i <= Math.sqrt(n); i++) {
				if (n % (i*i) == 0) {
					return false;
				}
			}
			return true;
		}
	</script>
</body>
</html>
