```c++
#include <iostream>
#include <string>
#include <librdkafka/rdkafkacpp.h>
class KafkaProducer {
public:
  KafkaProducer() {
    _conf = RdKafka::Conf::create(RdKafka::Conf::CONF_GLOBAL);
    std::string errstr;
    _conf->set("bootstrap.servers", "localhost:9092", errstr);
    _producer = RdKafka::Producer::create(_conf.get(), errstr);
  }
  void send(std::string const& message, std::string const& topic) {
    auto* t = _producer->topic(topic, RdKafka::Topic::PARTITION_UA);
    RdKafka::ErrorCode resp = _producer->produce(
        t, RdKafka::Topic::PARTITION_UA, RdKafka::Producer::RK_MSG_COPY,
        const_cast<char*>(message.c_str()), message.size(), nullptr, nullptr);
    delete t;
  }
private:
  std::unique_ptr<RdKafka::Conf> _conf;
  std::unique_ptr<RdKafka::Producer> _producer;
};
```
