  KafkaConsumer() {
    _conf = RdKafka::Conf::create(RdKafka::Conf::CONF_GLOBAL);
    std::string errstr;
    _conf->set("bootstrap.servers", "localhost:9092", errstr);
    _conf->set("group.id", "mygroup", errstr);
    _consumer = RdKafka::Consumer::create(_conf.get(), errstr);
  }
  void subscribe(std::string const& topic) {
    _topics.push_back(topic);
    _consumer->subscribe(_topics);
  }
  std::string consume() {
    RdKafka::Message* msg = _consumer->consume(1000);
    std::string result = "";
    if (msg->err() == RdKafka::ERR_NO_ERROR) {
      result = std::string(static_cast<char*>(msg->payload()), msg->len());
    }
    delete msg;
    return result;
  }
private:
  std::unique_ptr<RdKafka::Conf> _conf;
  std::unique_ptr<RdKafka::Consumer> _consumer;
  std::vector<std::string> _topics;
};
int main() {
  KafkaProducer producer;
  KafkaConsumer consumer;
  producer.send("hello world", "mytopic");
  consumer.subscribe("mytopic");
  std::string message = consumer.consume();
  std::cout << message << std::endl;
  return 0;
}
